package server

import (
	"fmt"
	"net/url"
	"slices"
	"strings"
)

// Values of a principal's check key.
const (
	// CheckVerify (default) fails closed when UAR settings are unreadable.
	CheckVerify = "verify"
	// CheckAssert records that the operator verified what the settings API
	// does not expose.
	CheckAssert = "assert"
)

// LLMConfig is the llm section: the OpenAI-compatible model backend of the
// agent loop. The section is absent by default, and then nothing is mounted
// and no model call is made. APIKey is a reference to an environment variable
// or a file, never the key.
type LLMConfig struct {
	BaseURL string     `json:"base_url"`
	Model   string     `json:"model"`
	APIKey  *SecretRef `json:"api_key"`
	// Timeout is the per-request limit as a duration string ("60s" by default).
	Timeout string `json:"timeout"`
}

// AgentConfig is the agent section: the loop limits, the AG-UI and A2A switches
// and the AG-UI browser origin allowlist.
type AgentConfig struct {
	// AGUI is agent.agui: serve POST /agui (off by default).
	AGUI bool `json:"agui"`
	// A2A is agent.a2a: serve POST /a2a and the agent card (off by default).
	A2A bool `json:"a2a"`
	// OriginAllowlist is agent.origin_allowlist: page origins allowed to call
	// /agui from a browser (empty by default: none).
	OriginAllowlist []string   `json:"origin_allowlist"`
	Loop            LoopConfig `json:"loop"`
}

// LoopConfig is agent.loop: the limits every run enforces. Zero values take the
// contract defaults.
type LoopConfig struct {
	MaxSteps  int    `json:"max_steps"`
	MaxTokens int    `json:"max_tokens"`
	WallClock string `json:"wall_clock"`
}

// EmbeddingsConfig is the embeddings section. It is absent by default, and
// then no store is opened, no process is started and no embedder is contacted.
// Credentials are references, never values. The policy keys (auto, MIME
// allowlist, size cap, chunking) belong to the index lifecycle and are not
// read here.
type EmbeddingsConfig struct {
	// Mode is "embedded" or "remote".
	Mode     string `json:"mode"`
	Embedded *struct {
		SurrealBinary string `json:"surreal_binary"`
		DataDir       string `json:"data_dir"`
		MinVersion    string `json:"min_version"`
	} `json:"embedded"`
	Remote *struct {
		Endpoint   string     `json:"endpoint"`
		Namespace  string     `json:"namespace"`
		Database   string     `json:"database"`
		Credential *SecretRef `json:"credential"`
	} `json:"remote"`
	Embedder *struct {
		BaseURL    string     `json:"base_url"`
		Model      string     `json:"model"`
		Dimensions int        `json:"dimensions"`
		APIKey     *SecretRef `json:"api_key"`
	} `json:"embedder"`
	// Policy says what is indexed; absent means the contract defaults and no
	// automatic indexing.
	Policy *struct {
		Auto          bool     `json:"auto"`
		MIMEAllowlist []string `json:"mime_allowlist"`
		MaxBytes      int      `json:"max_bytes"`
		ChunkChars    int      `json:"chunk_chars"`
	} `json:"policy"`
}

// BackendHosts returns the hosts ipfs mcp itself would forward node content
// to: the llm endpoint, the embedder endpoint and a remote vector store. Each
// must be covered by the egress_ack of a principal whose content flows there.
func (c *Config) BackendHosts() []string {
	var hosts []string
	add := func(raw string) {
		if h := HostFromURL(raw); h != "" && !slices.Contains(hosts, h) {
			hosts = append(hosts, h)
		}
	}
	if c.LLM != nil {
		add(c.LLM.BaseURL)
	}
	if c.Embeddings != nil {
		if c.Embeddings.Embedder != nil {
			add(c.Embeddings.Embedder.BaseURL)
		}
		if c.Embeddings.Remote != nil {
			add(c.Embeddings.Remote.Endpoint)
		}
	}
	return hosts
}

// usesBackend reports whether a principal kind is served by ipfs mcp's own
// agent surface, so its content reaches the llm and embedder hosts. A
// human-mcp host and UAR bring their own model, which egress_ack and the UAR
// preflight cover instead.
func usesBackend(kind string) bool { return kind == KindUI || kind == KindA2A }

// configuredIdentity builds the identity of a configured principal: its
// grants, egress acknowledgement and assertions.
func (c *Config) configuredIdentity(p PrincipalConfig) Identity {
	id := NewIdentity(Principal{ID: p.Name, Kind: p.Kind}, p.Groups, p.WriteGroups, p.DestructiveGroups)
	id.Configured = true
	id.EgressAck = slices.Clone(p.EgressAck)
	id.ShellCapable = p.ShellCapable
	id.Check = p.Check
	if p.UAR != nil {
		u := *p.UAR
		id.UAR = &u
	}
	if usesBackend(p.Kind) {
		id.BackendHosts = c.BackendHosts()
	}
	return id
}

// validatePrincipals enforces the rules the JSON schema cannot express.
func (c *Config) validatePrincipals() error {
	seen := make(map[string]struct{}, len(c.Principals))
	for i, p := range c.Principals {
		at := fmt.Sprintf("principals[%d] (%s)", i, p.Name)
		if p.Name == OperatorPrincipalID {
			return fmt.Errorf("%s: the name %q is reserved for the --auth-token-* operator", at, OperatorPrincipalID)
		}
		if _, dup := seen[p.Name]; dup {
			return fmt.Errorf("%s: the name is used twice", at)
		}
		seen[p.Name] = struct{}{}
		if p.Kind == KindUAR {
			if p.UAR == nil || p.UAR.CardURL == "" {
				return fmt.Errorf("%s: a principal of kind uar needs uar.card_url, the address the check-uar preflight may contact", at)
			}
			if u, err := url.Parse(p.UAR.CardURL); err != nil || u.Host == "" || strings.ContainsAny(u.Host, " ") {
				return fmt.Errorf("%s: uar.card_url is not a valid URL", at)
			}
			continue
		}
		if p.UAR != nil {
			return fmt.Errorf("%s: the uar block is only valid for kind uar", at)
		}
		if p.Check == CheckAssert {
			return fmt.Errorf("%s: check: assert is only valid for kind uar", at)
		}
	}
	return nil
}

===== mcp/server/policy.go =====
package server

import (
	"context"
	"fmt"
	"log/slog"
	"slices"
	"sync"
	"time"
)

// Restriction reasons for grants withdrawn by policy.
const (
	// ReasonShellCapableUnasserted: --confirm=cli is on and the principal has
	// no shell_capable: false assertion.
	ReasonShellCapableUnasserted = "shell_capable_unasserted"
	// ReasonUARCheckFailed: the UAR preflight refused the principal.
	ReasonUARCheckFailed = "uar_check_failed"
)

// uarCheckTimeout bounds one whole preflight (card, probe and settings).
const uarCheckTimeout = 25 * time.Second

// uarGuard runs and caches the per-principal UAR preflight.
type uarGuard struct {
	checker *UARChecker
	now     func() time.Time
	log     *slog.Logger

	mu         sync.Mutex
	kuboListen string
	entries    map[string]*uarEntry
}

type uarEntry struct {
	mu     sync.Mutex
	have   bool
	at     time.Time
	report UARReport
}

func newUARGuard(log *slog.Logger, now func() time.Time, opts ...UARCheckerOption) *uarGuard {
	return &uarGuard{checker: NewUARChecker(nil, now, opts...), now: now, log: log, entries: map[string]*uarEntry{}}
}

func (g *uarGuard) setKuboListen(addr string) {
	g.mu.Lock()
	defer g.mu.Unlock()
	g.kuboListen = addr
}

// report returns the principal's verdict. fresh forces a new check, which a
// session initialize always does; otherwise a verdict younger than the
// contract's recheck interval (agentic/uar-preflight.json) is reused. A
// settings change is therefore seen on the next request after the interval,
// and on the next session at once.
func (g *uarGuard) report(ctx context.Context, id Identity, fresh bool) UARReport {
	g.mu.Lock()
	e, ok := g.entries[id.ID]
	if !ok {
		e = &uarEntry{}
		g.entries[id.ID] = e
	}
	listen := g.kuboListen
	g.mu.Unlock()

	e.mu.Lock()
	defer e.mu.Unlock()
	if e.have && !fresh && g.now().Sub(e.at) < g.checker.recheck() {
		return e.report
	}
	// The check does not depend on the request: a client that gives up must not
	// leave a refusal in the cache for everyone else.
	cctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), uarCheckTimeout)
	defer cancel()
	rep := g.checker.Check(cctx, UARCheckInput{UAR: *id.UAR, Check: id.Check, EgressAck: id.EgressAck, KuboListen: listen})
	if !e.have || e.report.Verdict() != rep.Verdict() || e.report.Revision != rep.Revision {
		g.log.Warn("uar preflight", "principal", id.ID, "verdict", rep.Verdict(), "version", rep.Version,
			"revision", rep.Revision, "findings", rep.Codes())
	}
	e.have, e.at, e.report = true, g.now(), rep
	return rep
}

// cliConfirmActive reports whether the headless CLI resolver is enabled.
func (s *Server) cliConfirmActive() bool {
	return slices.ContainsFunc(s.gate.list(), func(r Resolver) bool { return r.Name() == ResolverCLI })
}

func hasWrite(id Identity) bool {
	return len(id.WriteGroups) > 0 || len(id.DestructiveGroups) > 0
}

// withoutWrites returns the identity with its write and destructive grants
// withdrawn.
func withoutWrites(id Identity, why []Restriction) Identity {
	return Identity{
		Principal:    id.Principal,
		Scopes:       []string{ScopeRead},
		Groups:       slices.Clone(id.Groups),
		Configured:   id.Configured,
		EgressAck:    slices.Clone(id.EgressAck),
		BackendHosts: slices.Clone(id.BackendHosts),
		ShellCapable: id.ShellCapable,
		Check:        id.Check,
		UAR:          id.UAR,
		Restrictions: why,
	}
}

// shellRestriction is the restriction for a write principal without the
// shell_capable: false assertion while --confirm=cli is on, or nil.
func (s *Server) shellRestriction(id Identity) *Restriction {
	if !hasWrite(id) || !s.cliConfirmActive() {
		return nil
	}
	if id.ShellCapable != nil && !*id.ShellCapable {
		return nil
	}
	if id.ID == OperatorPrincipalID {
		// The --auth-token-* token has no config entry to carry the assertion,
		// and its holder is usually a coding agent with a shell. No exemption.
		return &Restriction{
			Reason: ReasonShellCapableUnasserted,
			Message: "--confirm=cli is on and the --auth-token-* operator identity has no shell_capable: false assertion; the CLI prompt has " +
				"no presence factor and the token is typically given to a coding agent that has a shell, so write groups are refused. " +
				"To grant writes under --confirm=cli, configure a principal in --mcp-config with kind human-mcp, its own credential, " +
				"the write_groups it needs and shell_capable: false",
		}
	}
	return &Restriction{
		Reason: ReasonShellCapableUnasserted,
		Message: "--confirm=cli is on and principal " + id.ID + " has no shell_capable: false assertion; the CLI prompt has no " +
			"presence factor, so a principal that may have a shell cannot be given write groups. Set shell_capable: false " +
			"only if the principal has no shell-capable tool",
	}
}

// applyPolicy returns the effective identity for a request: the configured
// grants minus whatever policy withdraws. A non-nil ToolError means the
// principal is disabled and the request is refused. initialize forces a fresh
// UAR preflight.
func (s *Server) applyPolicy(ctx context.Context, id Identity, initialize bool) (Identity, *ToolError) {
	var why []Restriction
	if r := s.shellRestriction(id); r != nil {
		why = append(why, *r)
	}
	if id.Kind == KindUAR && id.UAR != nil {
		rep := s.uar.report(ctx, id, initialize)
		switch rep.Verdict() {
		case VerdictRefuse:
			return id, &ToolError{
				Code:    CodePermissionDenied,
				Message: "principal " + id.ID + " (uar) is disabled by the check-uar preflight: " + rep.Summary(),
				Details: map[string]any{"reason": ReasonUARCheckFailed, "findings": rep.Findings},
			}
		case VerdictReadOnly:
			why = append(why, rep.Restrictions()...)
		}
	}
	if len(why) == 0 || !hasWrite(id) {
		return id, nil
	}
	return withoutWrites(id, why), nil
}

// StartupReport returns the lines ipfs mcp prints at startup about the
// configured principals: every grant policy withdraws and the outcome of the
// UAR preflight. It runs the preflight, so it contacts the operator-configured
// UAR address of each kind uar principal and no other.
func (s *Server) StartupReport(ctx context.Context, ids []Identity) []string {
	var lines []string
	for _, id := range ids {
		if r := s.shellRestriction(id); r != nil {
			lines = append(lines, fmt.Sprintf("principal %s: write groups refused: %s", id.ID, r.Message))
		}
		if id.Kind != KindUAR || id.UAR == nil {
			continue
		}
		rep := s.uar.report(ctx, id, true)
		switch v := rep.Verdict(); v {
		case VerdictOK:
			lines = append(lines, fmt.Sprintf("principal %s: check-uar ok (UAR %s)", id.ID, rep.Version))
		default:
			lines = append(lines, fmt.Sprintf("principal %s: check-uar %s: %s (run ipfs mcp check-uar for details)", id.ID, v, rep.Codes()))
		}
		if id.Check == CheckAssert {
			lines = append(lines, fmt.Sprintf("principal %s: check: assert is set; the operator asserts that the UAR instance "+
				"uses only local or acknowledged model and embedder hosts, has governance on, no shell-capable tool and no MCP server besides ipfs mcp, "+
				"and that it refuses unauthenticated requests; Kubo has not verified this", id.ID))
		}
	}
	return lines
}

